cat > /app/hierarchical_model.stan <<'EOF'
data {
  int<lower=1> N;
  array[N] int<lower=0> y;
  array[N] int<lower=0> n;
}
parameters {
  real<lower=0> alpha;
  real<lower=0> beta;
  vector<lower=0, upper=1>[N] theta;
}
model {
  // (alpha + beta)^(-5/2), up to a proportionality constant
  target += -2.5 * log(alpha + beta);
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF
cat > /app/analysis.R <<'EOF'
options(mc.cores = parallel::detectCores())
Sys.setenv(LOCAL_CPPFLAGS = "-O2")
library(rstan)
rstan_options(auto_write = TRUE)

input <- read.csv("/app/data.csv", header = TRUE)
stopifnot(all(c("y", "n") %in% names(input)))
stan_data <- list(
  N = nrow(input),
  y = as.integer(input$y),
  n = as.integer(input$n)
)

fit <- sampling(
  stan_model("/app/hierarchical_model.stan"),
  data = stan_data,
  chains = 4,
  iter = 100000,
  seed = 1,
  refresh = 1000,
  control = list(adapt_delta = 0.9, max_treedepth = 12)
)

s <- rstan::extract(fit, pars = c("alpha", "beta"), permuted = TRUE)
writeLines(sprintf("%.17g", mean(s$alpha)), "/app/posterior_alpha_mean.txt")
writeLines(sprintf("%.17g", mean(s$beta)), "/app/posterior_beta_mean.txt")
EOF
Rscript /app/analysis.R

